const {test}=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const {chromium}=require('playwright');
test('WhatsApp button has breathing room beneath Buy on desktop and mobile',async()=>{const browser=await chromium.launch({headless:true,executablePath:process.env.BE_BROWSER||'C:/Users/rcalmeida/AppData/Local/ms-playwright/chromium-1234/chrome-win64/chrome.exe'});try{let page=await browser.newPage();for(const width of [390,1440]){await page.setViewportSize({width,height:800});await page.setContent('<style>.row{display:flex;flex-wrap:wrap}.col-12{width:100%}input{display:block;width:100%;height:40px}'+fs.readFileSync('static/css/product-whatsapp.css','utf8')+'</style><form><div class="row"><div class="col-12"><input class="js-addtocart" type="submit" value="Comprar"></div><div class="col-12 eora-product-whatsapp-row"><a class="eora-product-whatsapp">Consulte-nos pelo WhatsApp</a></div></div></form>');let gap=await page.evaluate(()=>document.querySelector('.eora-product-whatsapp').getBoundingClientRect().top-document.querySelector('.js-addtocart').getBoundingClientRect().bottom);assert(gap>=10,`gap at ${width}px was ${gap}px`);}}finally{await browser.close()}});
